-- Add MM-DiT, introduced in arXiv 2403.03206.
-- Added 2026-10-18 from a scan of methods named by many recent papers but
-- missing from the catalog. The source paper gets the source evidence row (Introduced banner).

INSERT INTO methods (
    slug,
    name,
    full_name,
    description,
    keywords,
    area_id,
    introduced_year,
    source_paper_id,
    source_url,
    source_title,
    code_snippet_url,
    image_url,
    image_credit
)
VALUES (
    'mmdit',
    'MM-DiT',
    'Multimodal Diffusion Transformer (MM-DiT)',
    'MM-DiT (Multimodal Diffusion Transformer) is the text-to-image backbone introduced with Stable Diffusion 3. Unlike a standard [Diffusion Transformer](/methods/diffusion-transformer-dit), which injects text through cross-attention or pooled conditioning, MM-DiT processes text tokens and image-latent tokens as two streams with separate weights. Each modality has its own adaLN modulation, QKV projections and MLPs, and the two sequences are concatenated for a single joint attention operation. Information therefore flows in both directions between image and text. In SD3 the text stream comes from [CLIP](/methods/clip) ViT-L/14, OpenCLIP ViT-G/14 and [T5](/methods/t5)-XXL embeddings, and the model is trained as a [rectified flow](/methods/rectified-flow) with timestep sampling biased toward perceptually relevant noise scales. The paper reports improved text comprehension, typography and human preference ratings over cross-attention and UViT baselines. It also shows predictable scaling, where lower validation loss tracks better text-to-image quality, up to an 8B-parameter model. MM-DiT blocks, often called double-stream blocks, were adopted by later models such as [FLUX](/methods/flux) and by many video and audio generators.',
    'MMDiT, MM-DiT, multimodal diffusion transformer, multi-modal diffusion transformer',
    (
        SELECT id
        FROM areas
        WHERE name = 'Vision'
        LIMIT 1
    ),
    2024,
    (
        SELECT id
        FROM papers
        WHERE arxiv_id = '2403.03206'
        ORDER BY is_latest_version DESC, id DESC
        LIMIT 1
    ),
    NULL,
    'Scaling Rectified Flow Transformers for High-Resolution Image Synthesis',
    'https://github.com/Stability-AI/sd3.5/blob/main/mmditx.py',
    NULL,
    '[Scaling Rectified Flow Transformers for High-Resolution Image Synthesis](/paper/2403.03206)'
)
ON CONFLICT (slug) DO UPDATE
SET
    name = EXCLUDED.name,
    full_name = EXCLUDED.full_name,
    description = EXCLUDED.description,
    keywords = EXCLUDED.keywords,
    area_id = EXCLUDED.area_id,
    introduced_year = EXCLUDED.introduced_year,
    source_paper_id = EXCLUDED.source_paper_id,
    source_url = EXCLUDED.source_url,
    source_title = EXCLUDED.source_title,
    code_snippet_url = EXCLUDED.code_snippet_url,
    image_url = EXCLUDED.image_url,
    image_credit = EXCLUDED.image_credit,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO paper_methods (paper_id, method_id)
SELECT source_paper_id, id FROM methods
WHERE slug = 'mmdit' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT source_paper_id, id, 'source' FROM methods
WHERE slug = 'mmdit' AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

