INSERT INTO paper_method_exclusions (paper_id, method_id, reason)
SELECT paper_id, method_id, 'mmdit citation review 2026-10-18: cites the source without naming the method in title or abstract'
FROM mmdit_excluded_papers
ON CONFLICT (paper_id, method_id) DO UPDATE SET
    reason = EXCLUDED.reason,
    updated_at = now();

DELETE FROM paper_methods pm
USING mmdit_excluded_papers x
WHERE pm.paper_id = x.paper_id AND pm.method_id = x.method_id;

-- 67 local citers name the method in title or abstract.
CREATE TEMP TABLE mmdit_cited_papers ON COMMIT DROP AS
SELECT p.id AS paper_id, m.id AS method_id
FROM papers p
CROSS JOIN methods m
WHERE m.slug = 'mmdit'
  AND p.id IS DISTINCT FROM m.source_paper_id
  AND p.id IN (
        40814, 41023, 41789, 42180, 42337, 45814, 45944, 46068, 46456, 49279, 49822, 49847,
        50806, 50876, 51428, 51582, 52144, 52192, 52339, 52779, 53359, 53684, 53999, 54647,
        54837, 55090, 55309, 56656, 58360, 59650, 60492, 60587, 60978, 63917, 64301, 64791,
        65186, 66293, 69830, 69901, 70399, 73827, 82850, 82967, 84296, 84415, 85239, 85590,
        87630, 89638, 94236, 98415, 98763, 99830, 100711, 106839, 113803, 114034, 114231, 118430,
        118448, 118451, 118475, 118511, 119300, 122119, 122827
  );

INSERT INTO paper_methods (paper_id, method_id)
SELECT paper_id, method_id FROM mmdit_cited_papers x
WHERE NOT EXISTS (
    SELECT 1 FROM paper_method_exclusions e
    WHERE e.paper_id = x.paper_id AND e.method_id = x.method_id
)
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT x.paper_id, x.method_id, 'reference' FROM mmdit_cited_papers x
JOIN paper_methods pm ON pm.paper_id = x.paper_id AND pm.method_id = x.method_id
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

-- 99 papers match the method keywords (same matcher as the
-- daily keyword backfill).
CREATE TEMP TABLE mmdit_keyword_papers ON COMMIT DROP AS
SELECT p.id AS paper_id, m.id AS method_id
FROM papers p
CROSS JOIN methods m
WHERE m.slug = 'mmdit'
  AND p.id IS DISTINCT FROM m.source_paper_id
  AND p.id IN (
        38910, 40314, 40814, 41023, 41789, 42180, 42337, 43766, 44046, 45814, 45944, 46068,
        46456, 49279, 49822, 49847, 50806, 50876, 51428, 51503, 51582, 52063, 52144, 52192,
        52339, 52779, 53359, 53684, 53999, 54647, 54837, 55090, 55309, 55329, 56300, 56351,
        56591, 56656, 58360, 59650, 60492, 60587, 60756, 60978, 61166, 63917, 64114, 64301,
        64791, 65186, 65602, 66293, 66567, 69292, 69830, 69901, 70399, 71738, 73242, 73827,
        76792, 82850, 82967, 83918, 83924, 84296, 84415, 85239, 85437, 85590, 86722, 87630,
        89638, 94236, 98326, 98415, 98763, 99830, 100711, 103345, 103559, 104439, 104752, 106839,
        108085, 113803, 114034, 114231, 114287, 118430, 118448, 118451, 118475, 118511, 119300, 121276,
        122119, 122178, 122827
  );

INSERT INTO paper_methods (paper_id, method_id)
SELECT paper_id, method_id FROM mmdit_keyword_papers x
WHERE NOT EXISTS (
    SELECT 1 FROM paper_method_exclusions e
    WHERE e.paper_id = x.paper_id AND e.method_id = x.method_id
)
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT x.paper_id, x.method_id, 'keyword' FROM mmdit_keyword_papers x
JOIN paper_methods pm ON pm.paper_id = x.paper_id AND pm.method_id = x.method_id
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();
